import { useEffect, useId, useRef } from 'react';
import { AppHypercube3d, ENVIRONMENT_TYPE, COLOR_MAP_TYPE } from '../../lib/AppHypercube3d';

type Props = {
	webGPU?: boolean;
	performanceMode?: boolean;
	debuggerMode?: boolean;

	environmentType?: ENVIRONMENT_TYPE;
	fov?: number;
	ui?: boolean;

	colorMap?: COLOR_MAP_TYPE;

	setMoveForwardFn?: React.Dispatch<React.SetStateAction<() => void>>;
	setMoveBackwardFn?: React.Dispatch<React.SetStateAction<() => void>>;

	animationA?: React.Dispatch<React.SetStateAction<() => void>>;
	animationB?: React.Dispatch<React.SetStateAction<() => void>>;
};

type AppInstance = ReturnType<typeof AppHypercube3d.init>;

const setFn = (setter?: React.Dispatch<React.SetStateAction<() => void>>, action?: () => void) => {
	if (setter && action) {
		setter(() => () => action());
	}
};

const ReactHypercube = ({ 
	environmentType, 
	webGPU = false, performanceMode = true, debuggerMode = false, ui = false, 
	fov, colorMap,
	setMoveForwardFn, setMoveBackwardFn, animationA, animationB }: Props) => {
	const hasInitialized = useRef<Awaited<AppInstance> | undefined>(undefined);
	const divID = useId();
	useEffect(() => {
		if (hasInitialized.current !== undefined) return;

		const init = async () => {
			const instance = await AppHypercube3d.init({ divID, webGPU, performanceMode, environmentType, debuggerMode, ui });
			hasInitialized.current = instance;

			if (colorMap) {
				console.log(colorMap)
			}

			// .............................. view fns binding
			if (setMoveForwardFn) {
				setMoveForwardFn(() => {
					return () => {
						instance.moveCameraForward();
					};
				});
			}

			setFn(setMoveBackwardFn, () => instance.moveCameraBackward());
			setFn(animationA, () => instance.activateAnimationA());
			setFn(animationB, () => instance.activateAnimationB());
			// .............................. end view fns binding
		};

		init();

		return () => {
			if (hasInitialized.current && typeof hasInitialized.current?.destroy === 'function') {
				hasInitialized.current.destroy();
				console.warn('🧹 Destroyed Hypercube instance');
			}
		};
	}, [animationA, animationB, debuggerMode, divID, performanceMode, setMoveBackwardFn, setMoveForwardFn, webGPU]);

	useEffect(() => {
		hasInitialized.current?.shiftEnvironmentType(environmentType);
	}, [environmentType]);

	useEffect(() => {
		hasInitialized.current?.setFOV(fov);
	}, [fov]);

	const styles = { width: '100%', height: '100%' };

	return <div id={divID} style={styles}></div>;
};

export default ReactHypercube;

export { ENVIRONMENT_TYPE, COLOR_MAP_TYPE };
